for name,h in [('A',A),('B',B)]:
    raw=round(100*h['obs']/h['n'],1)
    exp=h['n']*h['exp_rate']
    smr=round(h['obs']/exp,2)
    print(f'hospital_{name}_raw_pct={raw}')
    print(f'hospital_{name}_smr={smr}')

